  // ============ Construct Function Inputs ============

  // Input: Two values for calculation
  const int a = 3;
  const int b = 4;

  // ============ Call Function to Get Return Value ============
  const int result = test_reactive_calculation(a, b);

  // ============ Assert to Verify Return Value ============

  EXPECT_EQ(result, 14);
}

}  // namespace test_reaction

