TEST(reaction, test_reactive_expression) {
  // ============ Construct Function Inputs ============

  // Input: Two values for expression
  const int a = 5;
  const int b = 3;

  // ============ Call Function to Get Return Value ============
  const int result = test_reactive_expression(a, b);

