```cpp
#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

class CacheProbeNode : public reaction::ObserverNode {
public:
    void valueChanged(bool changed = true) override {
        // Simple implementation that just calls parent
        this->notify(changed);
    }
};

struct CacheStatsSnapshot {
    size_t graphEntriesBeforeCleanup;
    size_t graphEntriesAfterCleanup;
    double graphHitRatioAfterCleanup;
};

CacheStatsSnapshot test_observer_cache_stats() {
    // 1. Create CacheProbeNode instances
    auto node1 = std::make_shared<CacheProbeNode>();
    auto node2 = std::make_shared<CacheProbeNode>();
    auto node3 = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto &graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(node1);
    graph.addNode(node2);
    graph.addNode(node3);

    // 4. Set up direct observer relationship (node1 observes node2)
    graph.addObserver(node2, node1);

    // 5. Set up transitive observer relationship (node1 observes node3 via node2)
    graph.addObserver(node3, node2);

    // 6. Create NodeSet to store collected observers
    reaction::NodeSet collectedObservers;

    // 7. Populate cache data by collecting observers multiple times
    // This will populate the cache with immediate observer data
    for (int i = 0; i < 10; ++i) {
        collectedObservers.clear();
        graph.collectObservers(node3, collectedObservers);
        collectedObservers.clear();
        graph.collectObservers(node2, collectedObservers);
    }

    // 8. Get cache statistics before cleanup
    auto statsBeforeCleanup = graph.getCacheStats();
    size_t entriesBeforeCleanup = statsBeforeCleanup.graphCache.entryCount;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfterCleanup = graph.getCacheStats();
    size_t entriesAfterCleanup = statsAfterCleanup.graphCache.entryCount;

    // Calculate hit ratio after cleanup
    double hitRatioAfterCleanup = 0.0;
    size_t totalAccesses = statsAfterCleanup.graphCache.hitCount + statsAfterCleanup.graphCache.missCount;
    if (totalAccesses > 0) {
        hitRatioAfterCleanup = static_cast<double>(statsAfterCleanup.graphCache.hitCount) / totalAccesses;
    }

    // 11. Close all nodes
    graph.closeNode(node1);
    graph.closeNode(node2);
    graph.closeNode(node3);

    // 12. Return cache stats snapshot
    return CacheStatsSnapshot{
        entriesBeforeCleanup,
        entriesAfterCleanup,
        hitRatioAfterCleanup
    };
}

}  // namespace test_reaction
