#include "test_resource_sbo.h"
#include <reaction/memory/sbo_resource.h>

namespace test_reaction {

ResourceSBOState test_resource_sbo() {
    // 1. Define type aliases for small and large resource types
    using SmallResourceType = int;
    using LargeResourceType = std::array<char, 1024>;

    // 2. Create small resource instance
    reaction::memory::SBOResource<SmallResourceType> smallResource(42);

    // 3. Create large resource instance
    reaction::memory::SBOResource<LargeResourceType> largeResource(LargeResourceType{});

    // 4. Query whether small resource uses SBO
    bool smallTypeUsesSBO = smallResource.isUsingSBO();

    // 5. Query whether large resource uses SBO
    bool largeTypeUsesSBO = largeResource.isUsingSBO();

    // 6. Return resource SBO state
    return ResourceSBOState{
        smallTypeUsesSBO,
        largeTypeUsesSBO
    };
}

}  // namespace test_reaction
```

This implementation:
1. Defines `SmallResourceType` as `int` (small enough for SBO) and `LargeResourceType` as a large array (too large for SBO)
2. Creates instances of `SBOResource` for both types
3. Queries the SBO status using the `isUsingSBO()` method
4. Returns a `ResourceSBOState` struct containing both results

The small resource should return `true` for SBO usage (stored inline), while the large resource should return `false` (stored on heap).

