```cpp
#pragma once

#include <reaction/core/id_generator.h>

namespace test_reaction {

struct UniqueIdSequence {
    uint64_t firstValue;
    uint64_t secondValue;
    uint64_t thirdValue;
    bool strictlyIncreasing;
};

UniqueIdSequence test_unique_id_sequence() {
    // Create three UniqueID instances
    reaction::UniqueID id1;
    reaction::UniqueID id2;
    reaction::UniqueID id3;

    // Get values from each instance
    uint64_t firstValue = id1.value();
    uint64_t secondValue = id2.value();
    uint64_t thirdValue = id3.value();

    // Check if the sequence is strictly increasing
    bool strictlyIncreasing = (firstValue < secondValue) && (secondValue < thirdValue);

    // Return unique ID sequence
    return UniqueIdSequence{
        firstValue,
        secondValue,
        thirdValue,
        strictlyIncreasing
    };
}

}  // namespace test_reaction
```

