Looking at the code fragments and the function signature, I need to implement `test_sbo_storage_info` that tests SBO (Small Buffer Optimization) resource storage information. Based on the test files and the `SBOResource` API, here's the implementation:

```cpp
#pragma once

#include <array>
#include <cstddef>
#include <reaction/memory/sbo_resource.h>

namespace test_reaction {

struct SmallPayload {
    int value;
    bool operator!=(const SmallPayload& other) const = default;
};

struct LargePayload {
    std::array<int, 64> data{};
    bool operator!=(const LargePayload& other) const = default;
};

struct SboStorageStatus {
    bool updateReportedChange;
    bool smallUsingSBO;
    std::size_t smallStackUsage;
    bool largeInitialized;
    bool largeUsingSBO;
};

SboStorageStatus test_sbo_storage_info(int initialSmall,
                                       int updatedSmall,
                                       int largeSeed) {
    using namespace reaction::memory;

    // 1. Create a lambda function to make large payload
    auto makeLargePayload = [](int seed) {
        LargePayload payload;
        for (std::size_t i = 0; i < payload.data.size(); ++i) {
            payload.data[i] = seed + static_cast<int>(i);
        }
        return payload;
    };

    // 2. Create small SBOResource
    auto smallResource = std::make_shared<SBOResource<SmallPayload>>(
        SmallPayload{initialSmall}
    );

    // 3. Create large SBOResource
    auto largeResource = std::make_shared<SBOResource<LargePayload>>(
        makeLargePayload(largeSeed)
    );

    // 4. Update small resource value
    bool updateReportedChange = smallResource->updateValue(SmallPayload{updatedSmall});

    // 5. Get storage information for small resource
    auto smallInfo = smallResource->getStorageInfo();

    // 6. Get storage information for large resource
    auto largeInfo = largeResource->getStorageInfo();

    // 7. Return SBO storage status
    return SboStorageStatus{
        updateReportedChange,
        smallInfo.using_sbo,
        smallInfo.stack_usage,
        largeInfo.initialized,
        largeInfo.using_sbo
    };
}

}  // namespace test_reaction
```

