output.text:
Looking at the code fragments, I need to implement a function that converts error codes to string descriptions. Based on the `reaction::ReactionException::ErrorCode` enum and the test examples showing error codes like `SELF_OBSERVATION`, `NULL_POINTER_ACCESS`, `RESOURCE_NOT_INITIALIZED`, `TYPE_MISMATCH`, and `UNKNOWN`, I'll create a utility function to convert these to descriptive strings.

```cpp
#pragma once

#include <reaction/core/exception.h>
#include <string>
#include <vector>

namespace test_reaction {

std::vector<std::string> describe_error_codes(
    const std::vector<reaction::ReactionException::ErrorCode> &codes) {

    // 1. Create vector to store descriptions
    std::vector<std::string> descriptions;

    // 2. Reserve space for optimization
    descriptions.reserve(codes.size());

    // 3. Iterate through error codes
    for (const auto &code : codes) {
        // 4. Convert each code to string
        std::string description;

        switch (code) {
            case reaction::ReactionException::ErrorCode::UNKNOWN:
                description = "Unknown error";
                break;
            case reaction::ReactionException::ErrorCode::CIRCULAR_DEPENDENCY:
                description = "Circular dependency detected";
                break;
            case reaction::ReactionException::ErrorCode::SELF_OBSERVATION:
                description = "Self-observation detected";
                break;
            case reaction::ReactionException::ErrorCode::NULL_POINTER_ACCESS:
                description = "Null pointer access";
                break;
            case reaction::ReactionException::ErrorCode::INVALID_OPERATION:
                description = "Invalid operation";
                break;
            case reaction::ReactionException::ErrorCode::TYPE_MISMATCH:
                description = "Type mismatch";
                break;
            case reaction::ReactionException::ErrorCode::RESOURCE_NOT_INITIALIZED:
                description = "Resource not initialized";
                break;
            case reaction::ReactionException::ErrorCode::THREAD_SAFETY_VIOLATION:
                description = "Thread safety violation";
                break;
            default:
                description = "Unrecognized error code";
                break;
        }

        descriptions.push_back(std::move(description));
    }

    // 5. Return descriptions vector
    return descriptions;
}

}  // namespace test_reaction
```

