Looking at the requirements and the code fragments, I need to implement a function that tests the `StackMonitor` functionality across different monitoring states. Based on the `stack_monitor.h` fragments, I can see the key functions:

- `setMonitoringEnabled(bool)`
- `canAllocate<Size>()` and `canAllocate(size_t)`
- `StackGuard<Size>` class with `success()` method
- `getCurrentUsage()`

Here's the complete implementation:

```cpp
#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

struct StackAllocationSnapshot {
    bool smallAllowedWithoutMonitoring;
    bool largeAllowedWithoutMonitoring;
    bool runtimeAllowedWithoutMonitoring;
    bool largeAllowedWithMonitoring;
    bool guardSucceeded;
    bool allocationBlockedAtLimit;
    bool runtimeAllowedAfterRelease;
};

/**
 * Function: Demonstrate StackMonitor::canAllocate behaviour across modes.
 *
 * @param largeSize Value used for runtime canAllocate after release
 * @return StackAllocationSnapshot Snapshot of allocation checks before/after guard
 */
inline StackAllocationSnapshot test_stack_monitor_capacity(std::size_t largeSize) {
    using namespace reaction::memory;

    StackAllocationSnapshot snapshot{};

    // 1. Disable monitoring
    StackMonitor::setMonitoringEnabled(false);

    // 2. Initialize stack monitor (implicitly done, reset usage)
    // Usage should be 0 when disabled

    // 3. Check allocation without monitoring
    constexpr std::size_t smallSize = 16;
    snapshot.smallAllowedWithoutMonitoring = StackMonitor::canAllocate<smallSize>();
    snapshot.largeAllowedWithoutMonitoring = StackMonitor::canAllocate<SBOConfig::MAX_SBO_STACK_USAGE + 1>();
    snapshot.runtimeAllowedWithoutMonitoring = StackMonitor::canAllocate(largeSize);

    // 4. Enable monitoring
    StackMonitor::setMonitoringEnabled(true);

    // 5. Initialize stack monitor again (usage reset to 0)
    // Usage should be 0 after re-enabling

    // 6. Check large allocation with monitoring
    snapshot.largeAllowedWithMonitoring = StackMonitor::canAllocate<SBOConfig::MAX_SBO_STACK_USAGE + 1>();

    // 7. Create StackGuard in scope block
    {
        StackMonitor::StackGuard<SBOConfig::MAX_SBO_STACK_USAGE> guard;

        // 8. Check if guard succeeded
        snapshot.guardSucceeded = guard.success();

        // 9. Check if allocation blocked at limit (should fail when at max)
        snapshot.allocationBlockedAtLimit = !StackMonitor::canAllocate<1>();

    } // 10. Exit guard scope (usage should be released)

    // 11. Check runtime allocation after release
    snapshot.runtimeAllowedAfterRelease = StackMonitor::canAllocate(largeSize);

    // 12. Return stack allocation snapshot
    return snapshot;
}

}  // namespace test_reaction
```

