```cpp
#pragma once

#include <reaction/cache/graph_cache.h>
#include <reaction/core/observer_node.h>
#include <memory>

namespace test_reaction {

struct NodeMetricsCacheSnapshot {
    std::size_t entriesBefore;
    std::size_t entriesAfterCache;
    std::size_t entriesAfterInvalidate;
    std::size_t hitCount;
    std::size_t missCount;
    double hitRatio;
    bool metricsCachedExists;
    bool metricsClearedAfterInvalidate;
};

inline NodeMetricsCacheSnapshot test_node_metrics_cache() {
    // 1. Create NodeMetricsCache instance
    reaction::NodeMetricsCache cache;

    // 2. Create ObserverNode instance
    auto node = std::make_shared<reaction::ObserverNode>();

    // 3. Get cache statistics before caching
    auto statsBefore = cache.getStats();
    std::size_t entriesBefore = statsBefore.entries;

    // 4. Query metrics before caching (should miss)
    const auto* metricsBefore = cache.getCachedNodeMetrics(node);
    bool missedBefore = (metricsBefore == nullptr);

    // 5. Cache node metrics
    cache.cacheNodeMetrics(node, true, 5, 3, 2);

    // 6. Query metrics after caching (should hit)
    const auto* metricsAfter = cache.getCachedNodeMetrics(node);
    bool metricsCachedExists = (metricsAfter != nullptr && metricsAfter->exists);

    // 7. Get cache statistics after caching
    auto statsAfterCache = cache.getStats();
    std::size_t entriesAfterCache = statsAfterCache.entries;
    std::size_t hitCount = statsAfterCache.hits;
    std::size_t missCount = statsAfterCache.misses;

    // 8. Invalidate all entries
    cache.invalidateAll();

    // 9. Query metrics after invalidation (should miss again)
    const auto* metricsAfterInvalidate = cache.getCachedNodeMetrics(node);
    bool metricsClearedAfterInvalidate = (metricsAfterInvalidate == nullptr);

    // 10. Get cache statistics after invalidation
    auto statsAfterInvalidate = cache.getStats();
    std::size_t entriesAfterInvalidate = statsAfterInvalidate.entries;

    // Calculate hit ratio
    double hitRatio = 0.0;
    if (hitCount + missCount > 0) {
        hitRatio = static_cast<double>(hitCount) / static_cast<double>(hitCount + missCount);
    }

    // 11. Return node metrics cache snapshot
    return NodeMetricsCacheSnapshot{
        entriesBefore,
        entriesAfterCache,
        entriesAfterInvalidate,
        hitCount,
        missCount,
        hitRatio,
        metricsCachedExists,
        metricsClearedAfterInvalidate
    };
}

}  // namespace test_reaction
