```cpp
#pragma once

#include <reaction/cache/cache_base.h>
#include <memory>
#include <chrono>

namespace test_reaction {

struct GenericCacheStatsSnapshot {
    std::size_t entriesBefore;
    std::size_t entriesAfterInsert;
    std::size_t entriesAfterInvalidate;
    std::size_t hitCount;
    std::size_t missCount;
    double hitRatio;
    bool firstLookupWasMiss;
    bool secondLookupWasHit;
};

GenericCacheStatsSnapshot test_generic_cache_base() {
    // 1. Define IntCache class inheriting from CacheBase
    class IntCache : public reaction::CacheBase<int, int> {
    public:
        // 2. Expose CacheBase methods using using declarations
        using CacheBase::getCachedValue;
        using CacheBase::cacheValue;
        using CacheBase::invalidateAllEntries;
        using CacheBase::triggerCleanupInternal;
        using CacheBase::getStatsInternal;

        explicit IntCache(size_t maxSize = 100, std::chrono::minutes ttl = std::chrono::minutes(5))
            : CacheBase(maxSize, ttl) {}
    };

    // 3. Create IntCache instance
    IntCache cache(100, std::chrono::minutes(5));

    // 4. Get initial cache statistics
    auto statsBefore = cache.getStatsInternal();
    std::size_t entriesBefore = statsBefore.entries;

    // 5. Perform initial lookup
    const int* firstLookup = cache.getCachedValue(42);
    bool firstLookupWasMiss = (firstLookup == nullptr);

    // 6. Insert value into cache
    cache.cacheValue(42, 100);

    // 7. Perform second lookup
    const int* secondLookup = cache.getCachedValue(42);
    bool secondLookupWasHit = (secondLookup != nullptr);

    // 8. Get cache statistics after insertion
    auto statsAfterInsert = cache.getStatsInternal();
    std::size_t entriesAfterInsert = statsAfterInsert.entries;

    // 9. Invalidate all cache entries
    cache.invalidateAllEntries();

    // 10. Trigger cleanup
    cache.triggerCleanupInternal();

    // 11. Get cache statistics after invalidation
    auto statsAfterInvalidate = cache.getStatsInternal();
    std::size_t entriesAfterInvalidate = statsAfterInvalidate.entries;
    std::size_t hitCount = statsAfterInvalidate.hitCount;
    std::size_t missCount = statsAfterInvalidate.missCount;

    double hitRatio = 0.0;
    if (hitCount + missCount > 0) {
        hitRatio = static_cast<double>(hitCount) / (hitCount + missCount);
    }

    // 12. Return generic cache stats snapshot
    return GenericCacheStatsSnapshot{
        entriesBefore,
        entriesAfterInsert,
        entriesAfterInvalidate,
        hitCount,
        missCount,
        hitRatio,
        firstLookupWasMiss,
        secondLookupWasHit
    };
}

}  // namespace test_reaction
